<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue';
import {useDesk} from '../../admin';
import {say} from '../../state';
import copy from '../../content/customer-notifications.json';
import MessagesPanel from './MessagesPanel.vue';
import SiteConversation from '../SiteConversation.vue';
const props=defineProps<{active:boolean}>(),{request}=useDesk();const phonePanel=ref<InstanceType<typeof MessagesPanel>>();const channel=ref('phone'),items=ref<any[]>([]),selected=ref(''),query=ref(''),unread=ref(false),error=ref('');let busy=false,alive=true,timer:ReturnType<typeof setInterval>;
async function load(){if(busy||!props.active||channel.value!=='site')return;busy=true;try{const result=await request<any>('/manage/site-messages?query='+encodeURIComponent(query.value)+'&unread='+unread.value);if(alive)items.value=result.items;}catch{error.value=say(copy.generic_error);}finally{busy=false;}}
watch([()=>props.active,channel],()=>{clearInterval(timer);if(props.active&&channel.value==='site'){void load();timer=setInterval(()=>void load(),5000);}},{immediate:true});onBeforeUnmount(()=>{alive=false;clearInterval(timer);});defineExpose({refresh:()=>channel.value==='phone'?phonePanel.value?.refresh():load()});
</script>
<template><div><nav class="customer-channel-tabs"><button :class="{selected:channel==='phone'}" @click="channel='phone'">{{say(copy.phone_messages)}}</button><button :class="{selected:channel==='site'}" @click="channel='site'">{{say(copy.site_messages)}}</button></nav><MessagesPanel ref="phonePanel" v-if="channel==='phone'" :active="active"/><section v-else class="staff-site-inbox"><p v-if="error" class="form-error">{{error}}</p><aside><input v-model="query" :placeholder="say(copy.search)" @input="load"/><label><input v-model="unread" type="checkbox" @change="load"/>{{say(copy.unread)}}</label><button v-for="item in items" :key="item.id" :class="{selected:selected===item.id}" @click="selected=item.id"><strong>{{item.name}}</strong><b v-if="item.unread">{{item.unread}}</b><span>{{item.latest?.body}}</span></button></aside><SiteConversation v-if="selected" :key="selected" :staff-id="selected"/></section></div></template>
<style scoped>.customer-channel-tabs{display:flex;gap:8px;margin:16px 0}.customer-channel-tabs button{padding:10px 16px;min-height:44px;border:1px solid #dce5ea;border-radius:20px}.customer-channel-tabs .selected,.staff-site-inbox button.selected{background:#e6f1f7}.staff-site-inbox{display:grid;grid-template-columns:260px minmax(0,1fr);gap:18px;align-items:start}.staff-site-inbox aside{display:flex;flex-direction:column;gap:10px;max-height:650px;overflow:auto}.staff-site-inbox aside>input{font-size:16px;padding:12px;min-width:0;border:1px solid #dce5ea;border-radius:9px}.staff-site-inbox aside label{display:flex;align-items:center;gap:8px;min-height:44px;font-size:13px}.staff-site-inbox aside button{text-align:left;padding:14px;border:1px solid #dce5ea;border-radius:12px;display:grid;grid-template-columns:1fr auto;gap:8px}.staff-site-inbox aside span{grid-column:1/-1;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;color:#80909b;font-size:12px}@media(max-width:760px){.staff-site-inbox{grid-template-columns:1fr}.staff-site-inbox aside{max-height:220px}}</style>
